  function adminDashboard(){
    return `${pageHead('Оперативный обзор','Состояние объектов, постов, смен и рисков за сегодня.',`${btn('Экспорт','download')}${btn('Создать смену','plus','primary')}`)}
    <div class="grid cols-4">${metric('Посты сейчас','28 / 30','+2 к вчера','shield')}${metric('Ожидают check-in','3','-1 за час','clock')}${metric('Активные инциденты','2','1 критический','alert')}${metric('Документы истекают','14','на 30 дней','file')}</div>
    <div class="split-60 section"><div class="card"><div class="card-head"><h3>Покрытие постов — 7 дней</h3><span class="meta">план / факт</span></div><div class="chart">${[['Пн',78],['Вт',88],['Ср',83],['Чт',94],['Пт',91],['Сб',72],['Вс',69]].map(([d,h],i)=>`<div class="bar ${i>4?'alt':''}" style="height:${h}%" data-label="${d}"></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Риски сейчас</h3><span class="meta">6 событий</span></div><div class="list">${mini('alert','NO_SHOW: Склад №7','Пост «Ворота», 08:00','danger')}${mini('clock','Check-in требует проверки','БЦ «Север», Иванов И.И.','warning')}${mini('file','Удостоверение истекает','Петров А.В. — через 9 дней','warning')}${mini('route','Обход пропущен','ТЦ «Галерея», маршрут №2','danger')}</div></div></div>
    <div class="grid cols-2 section"><div class="card"><div class="card-head"><h3>Ближайшие смены</h3><span class="meta">следующие 4 часа</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Пост</th><th>Сотрудник</th><th>Начало</th><th>Статус</th></tr></thead><tbody>${row('БЦ Север / КПП-1','Москва, Ленинградский пр-т',['Иванов И.И.','08:00',pill('IN PROGRESS','success')],'admin:shift')}${row('Склад №7 / Ворота','Промзона Восточная',['—','08:00',pill('UNFILLED','danger')],'admin:shift')}${row('ТЦ Галерея / Пост 2','Невский пр-т',['Петров А.В.','09:00',pill('READY','info')],'admin:shift')}</tbody></table></div></div><div class="card"><div class="card-head"><h3>Статусы документов</h3><span class="meta">247 сотрудников</span></div><div class="grid cols-2"><div class="donut"></div><div class="list">${mini('check','178 действуют','72% базы','success')}${mini('file','14 истекают','до 30 дней','warning')}${mini('alert','6 просрочены','требуют действия','danger')}</div></div></div></div>`;
  }

